CREATE TABLE "CicloIngreso" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "anio" INTEGER NOT NULL, "estado" TEXT NOT NULL DEFAULT 'BORRADOR', "proximoNumero" INTEGER NOT NULL DEFAULT 1, "inscripcionesDesde" DATETIME, "inscripcionesHasta" DATETIME, "retencionHasta" DATETIME, "creadoEn" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "actualizadoEn" DATETIME NOT NULL);
CREATE TABLE "Preinscripcion" ("id" TEXT NOT NULL PRIMARY KEY, "cicloId" INTEGER NOT NULL, "numeroSorteo" INTEGER NOT NULL, "nombres" TEXT NOT NULL, "apellido" TEXT NOT NULL, "dniCifrado" TEXT NOT NULL, "dniHuella" TEXT NOT NULL, "fechaNacimiento" DATETIME NOT NULL, "escuelaOrigen" TEXT, "emailContacto" TEXT NOT NULL, "telefonoContacto" TEXT NOT NULL, "estado" TEXT NOT NULL DEFAULT 'CONFIRMADA', "versionAvisoPrivacidad" TEXT NOT NULL, "consentimientoAceptadoEn" DATETIME NOT NULL, "creadoEn" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "actualizadoEn" DATETIME NOT NULL, "eliminadoEn" DATETIME, CONSTRAINT "Preinscripcion_cicloId_fkey" FOREIGN KEY ("cicloId") REFERENCES "CicloIngreso" ("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "Responsable" ("id" TEXT NOT NULL PRIMARY KEY, "preinscripcionId" TEXT NOT NULL, "orden" INTEGER NOT NULL, "nombres" TEXT NOT NULL, "apellido" TEXT NOT NULL, "vinculo" TEXT NOT NULL, "dniCifrado" TEXT, "telefono" TEXT NOT NULL, "email" TEXT, CONSTRAINT "Responsable_preinscripcionId_fkey" FOREIGN KEY ("preinscripcionId") REFERENCES "Preinscripcion" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "UsuarioAdministrativo" ("id" TEXT NOT NULL PRIMARY KEY, "email" TEXT NOT NULL, "nombreUsuario" TEXT, "nombreMostrado" TEXT NOT NULL, "passwordHash" TEXT NOT NULL, "rol" TEXT NOT NULL, "activo" BOOLEAN NOT NULL DEFAULT true, "intentosFallidos" INTEGER NOT NULL DEFAULT 0, "bloqueadoHasta" DATETIME, "ultimoAccesoEn" DATETIME, "passwordActualizadoEn" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "creadoEn" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "actualizadoEn" DATETIME NOT NULL);
CREATE TABLE "EmailPendiente" ("id" TEXT NOT NULL PRIMARY KEY, "preinscripcionId" TEXT NOT NULL, "destinatario" TEXT NOT NULL, "plantilla" TEXT NOT NULL, "estado" TEXT NOT NULL DEFAULT 'PENDIENTE', "intentos" INTEGER NOT NULL DEFAULT 0, "proximoIntentoEn" DATETIME, "enviadoEn" DATETIME, "ultimoErrorCodigo" TEXT, "creadoEn" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "actualizadoEn" DATETIME NOT NULL, CONSTRAINT "EmailPendiente_preinscripcionId_fkey" FOREIGN KEY ("preinscripcionId") REFERENCES "Preinscripcion" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "EventoAuditoria" ("id" TEXT NOT NULL PRIMARY KEY, "usuarioId" TEXT, "tipo" TEXT NOT NULL, "entidad" TEXT, "entidadId" TEXT, "detalles" TEXT, "ipHuella" TEXT, "creadoEn" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "EventoAuditoria_usuarioId_fkey" FOREIGN KEY ("usuarioId") REFERENCES "UsuarioAdministrativo" ("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE TABLE "SolicitudEliminacion" ("id" TEXT NOT NULL PRIMARY KEY, "preinscripcionId" TEXT NOT NULL, "solicitadaPorId" TEXT NOT NULL, "motivo" TEXT NOT NULL, "ejecutadaEn" DATETIME, "creadaEn" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "SolicitudEliminacion_preinscripcionId_fkey" FOREIGN KEY ("preinscripcionId") REFERENCES "Preinscripcion" ("id") ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT "SolicitudEliminacion_solicitadaPorId_fkey" FOREIGN KEY ("solicitadaPorId") REFERENCES "UsuarioAdministrativo" ("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE UNIQUE INDEX "CicloIngreso_anio_key" ON "CicloIngreso"("anio");
CREATE INDEX "Preinscripcion_cicloId_apellido_nombres_idx" ON "Preinscripcion"("cicloId", "apellido", "nombres");
CREATE UNIQUE INDEX "Preinscripcion_cicloId_numeroSorteo_key" ON "Preinscripcion"("cicloId", "numeroSorteo");
CREATE UNIQUE INDEX "Preinscripcion_cicloId_dniHuella_key" ON "Preinscripcion"("cicloId", "dniHuella");
CREATE UNIQUE INDEX "Responsable_preinscripcionId_orden_key" ON "Responsable"("preinscripcionId", "orden");
CREATE UNIQUE INDEX "UsuarioAdministrativo_email_key" ON "UsuarioAdministrativo"("email");
CREATE UNIQUE INDEX "UsuarioAdministrativo_nombreUsuario_key" ON "UsuarioAdministrativo"("nombreUsuario");
CREATE INDEX "EmailPendiente_estado_proximoIntentoEn_idx" ON "EmailPendiente"("estado", "proximoIntentoEn");
CREATE INDEX "EventoAuditoria_tipo_creadoEn_idx" ON "EventoAuditoria"("tipo", "creadoEn");
CREATE INDEX "EventoAuditoria_usuarioId_creadoEn_idx" ON "EventoAuditoria"("usuarioId", "creadoEn");
